"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import { IconButton } from "@mui/material";
import { Edit as EditIcon, Delete as DeleteIcon } from "@mui/icons-material";

export default function GestionGroupes() {
  const [etudiants, setEtudiants] = useState([]);
  const [selectedEtudiants, setSelectedEtudiants] = useState([]);
  const [groupes, setGroupes] = useState([]);
  const [choixGenerer, setChoixGenerer] = useState("");
  const [nombreGroupes, setNombreGroupes] = useState("");
  const [nombreEtudiantsParGroupe, setNombreEtudiantsParGroupe] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [etudiantsRes, groupesRes] = await Promise.all([
        axios.get("http://localhost:3001/api/etudiants"),
        axios.get("http://localhost:3001/api/groupes"),
      ]);
      setEtudiants(etudiantsRes.data);
      setGroupes(groupesRes.data);
    } catch (err) {
      console.error("Erreur de chargement :", err);
    }
  };

  const toggleSelection = (id) => {
    setSelectedEtudiants((prev) =>
      prev.includes(id) ? prev.filter((eid) => eid !== id) : [...prev, id]
    );
  };

  const genererGroupe = async () => {
    setIsLoading(true);
    const data = { etudiants: selectedEtudiants };

    if (choixGenerer === "parEtudiants") {
      data.nombreEtudiantsParGroupe = parseInt(nombreEtudiantsParGroupe);
    } else if (choixGenerer === "parGroupes") {
      data.nombreGroupes = parseInt(nombreGroupes);
    }

    try {
      await axios.post("http://localhost:3001/api/genererGroupes", data);
      alert("Groupes générés !");
      fetchData();
      setSelectedEtudiants([]);
    } catch (err) {
      console.error("Erreur de génération :", err);
    } finally {
      setIsLoading(false);
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Confirmer suppression du groupe ?")) return;
    try {
      await axios.delete(`http://localhost:3001/api/supprimerGroupe/${idGroupe}`);
      alert("Groupe supprimé !");
      fetchData();
    } catch (err) {
      console.error("Erreur de suppression :", err);
    }
  };

  return (
    <div className="container mx-auto p-6">
      <h2 className="text-xl font-bold mb-4 text-center text-blue-600">
        Gestion des Groupes
      </h2>

      {/* Formulaire de génération */}
      <div className="flex flex-col gap-4 mb-6">
        <select
          value={choixGenerer}
          onChange={(e) => setChoixGenerer(e.target.value)}
          className="border p-2 rounded"
        >
          <option value="">Sélectionner une méthode</option>
          <option value="parEtudiants">Par nombre d'étudiants par groupe</option>
          <option value="parGroupes">Par nombre de groupes</option>
        </select>

        {choixGenerer === "parEtudiants" && (
          <input
            type="number"
            value={nombreEtudiantsParGroupe}
            onChange={(e) => setNombreEtudiantsParGroupe(e.target.value)}
            className="border p-2 rounded"
            placeholder="Nombre d'étudiants par groupe"
          />
        )}

        {choixGenerer === "parGroupes" && (
          <input
            type="number"
            value={nombreGroupes}
            onChange={(e) => setNombreGroupes(e.target.value)}
            className="border p-2 rounded"
            placeholder="Nombre de groupes"
          />
        )}

        <button
          onClick={genererGroupe}
          className="bg-green-500 text-white px-4 py-2 rounded"
          disabled={isLoading}
        >
          {isLoading ? "Génération en cours..." : "Générer Groupes"}
        </button>
      </div>

      {/* Table des étudiants et groupes */}
      <table className="min-w-full bg-white border border-gray-300">
        <thead>
          <tr className="bg-gray-200">
            <th className="border px-4 py-2">Étudiant</th>
            <th className="border px-4 py-2">Groupe</th>
            <th className="border px-4 py-2">Actions</th>
          </tr>
        </thead>
        <tbody>
          {etudiants.map((etudiant) => (
            <tr key={etudiant.idEtudiant} className="text-center">
              <td className="border px-4 py-2">
                <input
                  type="checkbox"
                  checked={selectedEtudiants.includes(etudiant.idEtudiant)}
                  onChange={() => toggleSelection(etudiant.idEtudiant)}
                  disabled={etudiant.idGroupe}
                  className="mr-2"
                />
                {etudiant.nom} {etudiant.prenom}
              </td>
              <td className="border px-4 py-2">{etudiant.nomGroupe || "-"}</td>
              <td className="border px-4 py-2">
                {etudiant.idGroupe && (
                  <>
                    <IconButton color="error" onClick={() => deleteGroupe(etudiant.idGroupe)}>
                      <DeleteIcon />
                    </IconButton>
                  </>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Liste des groupes */}
      <div className="mt-6">
        <h3 className="text-lg font-semibold mb-2 text-blue-500">Liste des Groupes</h3>
        {groupes.length === 0 ? (
          <p className="text-gray-600">Aucun groupe disponible.</p>
        ) : (
          groupes.map((groupe) => (
            <div key={groupe.idGroupe} className="border p-4 mb-2">
              <h4 className="text-lg font-bold">{groupe.nomGroupe}</h4>
              <p>{groupe.etudiants.join(", ")}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}
